// Checks and a plain-language overview for a visitor's own before/after images. Everything here runs in the browser on
// brightness values of ordinary pictures: it is NOT calibrated backscatter, produces no dB, and never names a cause.
// The "overview" is written by fixed rules from the measured statistics. It is not generated by an AI model.

export interface Gray { width: number; height: number; luma: Uint8ClampedArray; valid: Uint8Array }
export type CheckStatus = "pass" | "warn" | "fail" | "pending";
export interface Check { id: string; label: string; status: CheckStatus; detail: string }
export interface PairStats {
  validPixels: number; meanBefore: number; meanAfter: number; stdBefore: number; stdAfter: number;
  /** Mean of (after − before) brightness on valid pixels, in 0–255 brightness units. */
  meanShift: number; changedFraction: number; clippedBefore: number; clippedAfter: number;
}
export interface PairAnalysis { checks: Check[]; stats: PairStats | null; usable: boolean; overview: string[] }

export const MAX_BYTES = 25 * 1024 * 1024;
/** A pixel counts as "changed" when its brightness moved by more than this many of 255 levels. */
export const CHANGE_LEVELS = 32;

export function toGray(rgba: Uint8ClampedArray, width: number, height: number): Gray {
  if (rgba.length !== width * height * 4) throw new Error("Image size does not match its pixels");
  const luma = new Uint8ClampedArray(width * height), valid = new Uint8Array(width * height);
  for (let i = 0, p = 0; i < rgba.length; i += 4, p++) {
    luma[p] = Math.round(0.2126 * rgba[i] + 0.7152 * rgba[i + 1] + 0.0722 * rgba[i + 2]);
    valid[p] = rgba[i + 3] >= 128 ? 1 : 0;
  }
  return { width, height, luma, valid };
}

export function acceptableFile(file: { name: string; type: string; size: number }): string | null {
  if (!/^image\/(png|jpeg|webp)$/.test(file.type)) return "Use a PNG, JPEG or WebP image. HDF5 and other science products are processed offline and cannot be uploaded here.";
  if (file.size <= 0) return "The file is empty.";
  if (file.size > MAX_BYTES) return "The file is larger than 25 MB.";
  return null;
}

/** Brightness difference as the same blue-white-red colours the published difference pictures use, ready for blendChanges. */
export function differenceRgba(before: Gray, after: Gray): Uint8ClampedArray {
  if (before.width !== after.width || before.height !== after.height) throw new Error("Images must be the same size");
  const out = new Uint8ClampedArray(before.width * before.height * 4);
  for (let p = 0; p < before.luma.length; p++) {
    if (!before.valid[p] || !after.valid[p]) continue; // masked pixels stay fully transparent
    const d = after.luma[p] - before.luma[p], t = Math.min(1, Math.abs(d) / 96), keep = Math.round(255 * (1 - t));
    out.set(d >= 0 ? [255, keep, keep, 255] : [keep, keep, 255, 255], p * 4);
  }
  return out;
}

function moments(g: Gray) {
  let n = 0, s = 0, s2 = 0, clip = 0;
  for (let p = 0; p < g.luma.length; p++) if (g.valid[p]) { n++; s += g.luma[p]; s2 += g.luma[p] * g.luma[p]; if (g.luma[p] === 0 || g.luma[p] === 255) clip++; }
  const m = n ? s / n : 0;
  return { n, mean: m, std: n ? Math.sqrt(Math.max(0, s2 / n - m * m)) : 0, clip: n ? clip / n : 0 };
}

export function analyzePair(before: Gray | null, after: Gray | null): PairAnalysis {
  const checks: Check[] = [];
  const add = (id: string, label: string, status: CheckStatus, detail: string) => checks.push({ id, label, status, detail });
  if (!before || !after) {
    add("loaded", "Both images loaded", "pending", "Choose a before image and an after image to run the checks.");
    return { checks, stats: null, usable: false, overview: ["Add both images to run the checks."] };
  }
  add("loaded", "Both images loaded", "pass", `${before.width}×${before.height} and ${after.width}×${after.height} pixels.`);
  const sameSize = before.width === after.width && before.height === after.height;
  add("size", "Same size and framing", sameSize ? "pass" : "fail", sameSize ? "Pixel grids line up one-to-one." : "The images differ in size, so pixels do not correspond. Export both from the same grid and try again. Nothing is resampled for you.");
  if (!sameSize) return { checks, stats: null, usable: false, overview: ["The images are different sizes, so no pixel comparison was made."] };
  const mb = moments(before), ma = moments(after);
  const shared = (() => { let n = 0; for (let p = 0; p < before.valid.length; p++) if (before.valid[p] && after.valid[p]) n++; return n; })();
  const total = before.width * before.height, frac = shared / total;
  add("valid", "Pixels present on both dates", frac >= 0.9 ? "pass" : frac >= 0.5 ? "warn" : "fail", `${(frac * 100).toFixed(1)}% of pixels are opaque in both images; transparent pixels are treated as no data.`);
  const flat = mb.std < 2 || ma.std < 2;
  add("contrast", "Images have real contrast", flat ? "fail" : "pass", flat ? "One image is almost a single shade, so a comparison would be meaningless." : `Brightness spread ${mb.std.toFixed(0)} and ${ma.std.toFixed(0)} of 255.`);
  const worstClip = Math.max(mb.clip, ma.clip);
  add("clipping", "Not clipped to black or white", worstClip < 0.2 ? "pass" : "warn", `${(mb.clip * 100).toFixed(1)}% and ${(ma.clip * 100).toFixed(1)}% of pixels sit at pure black or white. Clipped areas hide real differences.`);
  const meanGap = Math.abs(ma.mean - mb.mean);
  add("exposure", "Similar overall brightness", meanGap < 25 ? "pass" : "warn", `Average brightness differs by ${meanGap.toFixed(1)} of 255. A large gap usually means different display scaling, not different ground.`);
  add("calibration", "Calibrated radar values", "warn", "These are picture brightness values, not calibrated backscatter. No dB or physical quantity is computed. Use the NISAR studies for published, calibrated numbers.");
  const usable = !checks.some((c) => c.status === "fail");
  if (!usable) return { checks, stats: null, usable, overview: ["At least one check failed, so no change statistics are shown."] };
  let changed = 0, shiftSum = 0;
  for (let p = 0; p < before.luma.length; p++) {
    if (!before.valid[p] || !after.valid[p]) continue;
    const d = after.luma[p] - before.luma[p]; shiftSum += d;
    if (Math.abs(d) > CHANGE_LEVELS) changed++;
  }
  const stats: PairStats = { validPixels: shared, meanBefore: mb.mean, meanAfter: ma.mean, stdBefore: mb.std, stdAfter: ma.std, meanShift: shared ? shiftSum / shared : 0, changedFraction: shared ? changed / shared : 0, clippedBefore: mb.clip, clippedAfter: ma.clip };
  return { checks, stats, usable, overview: describe(stats, checks) };
}

function describe(s: PairStats, checks: Check[]): string[] {
  const pct = (v: number) => `${(v * 100).toFixed(1)}%`;
  const lines: string[] = [];
  const scope = s.changedFraction < 0.02 ? "very little" : s.changedFraction < 0.15 ? "a modest share" : s.changedFraction < 0.4 ? "a large share" : "most";
  lines.push(`${pct(s.changedFraction)} of the ${s.validPixels.toLocaleString("en-US")} compared pixels changed brightness by more than ${CHANGE_LEVELS} of 255 levels: ${scope} of the scene.`);
  const dir = Math.abs(s.meanShift) < 3 ? "about the same brightness overall" : s.meanShift > 0 ? "brighter overall" : "darker overall";
  lines.push(`The after image is ${dir} (average shift ${s.meanShift >= 0 ? "+" : "−"}${Math.abs(s.meanShift).toFixed(1)} of 255).`);
  const flagged = checks.filter((c) => c.status === "warn" && c.id !== "calibration");
  if (flagged.length) lines.push(`Treat the result with extra care: ${flagged.map((c) => c.label.toLowerCase()).join("; ")} raised a warning.`);
  lines.push("This overview is produced by fixed rules from the numbers above, not by an AI model, and it runs entirely on your device. It cannot say why anything changed. Brightness can shift with display scaling, season, moisture, noise or processing. Independent evidence is needed before naming a cause.");
  return lines;
}
